from itertools import combinations
import random

def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS/DFS to find cycles
    def dfs(start, current, visited, path_len):
        if path_len == length:
            return start in adj[current]
        for neighbor in adj[current]:
            if neighbor == start and path_len == length - 1:
                return True
            if neighbor not in visited and neighbor != start:
                visited.add(neighbor)
                if dfs(start, neighbor, visited, path_len + 1):
                    return True
                visited.remove(neighbor)
        return False

    for start in range(n):
        visited = {start}
        for neighbor in adj[start]:
            visited.add(neighbor)
            if dfs(start, neighbor, visited, 2):
                return True
            visited.remove(neighbor)
    return False

def check_girth(edges, n, min_girth):
    """Check if graph has girth at least min_girth."""
    for length in range(3, min_girth):
        if has_cycle_of_length(edges, n, length):
            return False
    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(vertex):
        if vertex == n:
            return True
        for color in range(k):
            valid = True
            for neighbor in adj[vertex]:
                if colors[neighbor] == color:
                    valid = False
                    break
            if valid:
                colors[vertex] = color
                if backtrack(vertex + 1):
                    return True
                colors[vertex] = -1
        return False

    return backtrack(0)

